CREATE OR REPLACE FUNCTION fb_table_stats(tname text) RETURNS jsonb LANGUAGE sql SECURITY DEFINER AS $$ SELECT jsonb_build_object('seqScan', COALESCE(t.seq_scan,0), 'seqTup', COALESCE(t.seq_tup_read,0), 'idxScan', COALESCE(t.idx_scan,0), 'idxTup', COALESCE(t.idx_tup_fetch,0), 'blks', COALESCE(io.heap_blks_read,0)+COALESCE(io.heap_blks_hit,0)) FROM pg_stat_user_tables t JOIN pg_statio_user_tables io USING(relid) WHERE t.relname = tname $$;
